      expect(composite.computeDiscountCents(-500)).toBe(0);
    });

    it("defaults to sum mode when not specified", () => {
      const composite = new CompositeDiscountPolicy([
        new PercentageDiscountPolicy(10),
        new FixedAmountDiscountPolicy(200),
      ]);
      // sum mode: 10% of 5000 = 500, fixed 200 → 700
      expect(composite.computeDiscountCents(5_000)).toBe(700);
    });
  });

  describe("chain mode", () => {
    it("applies discounts sequentially on remaining subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [
          new PercentageDiscountPolicy(10), // 10% of 10000 = 1000, remaining 9000
          new PercentageDiscountPolicy(10), // 10% of 9000 = 900, remaining 8100
        ],
        "chain",
      );
      expect(composite.computeDiscountCents(10_000)).toBe(1_900);
    });

    it("ordering affects chained results", () => {
      const policyA = new CompositeDiscountPolicy(
        [
          new FixedAmountDiscountPolicy(1_000), // remaining 9000
          new PercentageDiscountPolicy(10),      // 10% of 9000 = 900
        ],
        "chain",
      );
      const policyB = new CompositeDiscountPolicy(
        [
          new PercentageDiscountPolicy(10),      // 10% of 10000 = 1000, remaining 9000
          new FixedAmountDiscountPolicy(1_000),  // min(1000, 9000) = 1000
        ],
        "chain",
      );
      expect(policyA.computeDiscountCents(10_000)).toBe(1_900);
      expect(policyB.computeDiscountCents(10_000)).toBe(2_000);
    });

    it("stops accumulating once remaining hits 0", () => {
      const composite = new CompositeDiscountPolicy(
        [
          new FixedAmountDiscountPolicy(10_000), // takes all 10000
          new PercentageDiscountPolicy(50),       // 50% of 0 = 0
        ],
        "chain",
      );
      expect(composite.computeDiscountCents(10_000)).toBe(10_000);
    });

    it("returns 0 when subtotal is 0", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "chain",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });
  });
});
