import { describe, it, expect } from "vitest";
import {
  NoDiscountPolicy,
  PercentageDiscountPolicy,
  FixedAmountDiscountPolicy,
  CompositeDiscountPolicy,
} from "../src/pricing.ts";

describe("NoDiscountPolicy", () => {
  const policy = new NoDiscountPolicy();

  it.each([0, 100, 999_99, -50])(
    "returns 0 for subtotal %i",
    (subtotal) => {
      expect(policy.computeDiscountCents(subtotal)).toBe(0);
    },
  );
});

describe("PercentageDiscountPolicy", () => {
  describe("constructor validation", () => {
    it.each([-1, 101, NaN, Infinity, -Infinity])(
      "rejects invalid percent %s",
      (pct) => {
        expect(() => new PercentageDiscountPolicy(pct)).toThrow(RangeError);
      },
    );

    it.each([0, 50, 100])("accepts valid percent %i", (pct) => {
      expect(() => new PercentageDiscountPolicy(pct)).not.toThrow();
    });
  });

  it("computes 10% of 10000 = 1000", () => {
    const policy = new PercentageDiscountPolicy(10);
    expect(policy.computeDiscountCents(10_000)).toBe(1_000);
  });

  it("rounds down fractional cents (15% of 999 = 149.85 → 149)", () => {
    const policy = new PercentageDiscountPolicy(15);
    expect(policy.computeDiscountCents(999)).toBe(149);
  });

  it("returns 0 when subtotal is 0", () => {
    const policy = new PercentageDiscountPolicy(50);
    expect(policy.computeDiscountCents(0)).toBe(0);
  });

  it("returns 0 when subtotal is negative", () => {
    const policy = new PercentageDiscountPolicy(50);
    expect(policy.computeDiscountCents(-500)).toBe(0);
  });

  it("100% returns the full subtotal", () => {
    const policy = new PercentageDiscountPolicy(100);
    expect(policy.computeDiscountCents(5000)).toBe(5000);
  });

  it("0% returns 0", () => {
    const policy = new PercentageDiscountPolicy(0);
    expect(policy.computeDiscountCents(5000)).toBe(0);
  });
});

describe("FixedAmountDiscountPolicy", () => {
  describe("constructor validation", () => {
    it.each([-1, -100])("rejects negative amount %i", (amt) => {
      expect(() => new FixedAmountDiscountPolicy(amt)).toThrow(RangeError);
    });

    it("rejects non-integer amount", () => {
      expect(() => new FixedAmountDiscountPolicy(10.5)).toThrow(RangeError);
    });

    it("accepts 0", () => {
      expect(() => new FixedAmountDiscountPolicy(0)).not.toThrow();
    });
  });

  it("returns full amount when subtotal exceeds it", () => {
    const policy = new FixedAmountDiscountPolicy(500);
    expect(policy.computeDiscountCents(10_000)).toBe(500);
  });

  it("caps discount at subtotal when amount exceeds subtotal", () => {
    const policy = new FixedAmountDiscountPolicy(5_000);
    expect(policy.computeDiscountCents(3_000)).toBe(3_000);
  });

  it("returns 0 when subtotal is 0", () => {
    const policy = new FixedAmountDiscountPolicy(500);
    expect(policy.computeDiscountCents(0)).toBe(0);
  });

  it("returns 0 when subtotal is negative", () => {
    const policy = new FixedAmountDiscountPolicy(500);
    expect(policy.computeDiscountCents(-100)).toBe(0);
  });
});

describe("CompositeDiscountPolicy", () => {
  it("rejects empty policies array", () => {
    expect(() => new CompositeDiscountPolicy([])).toThrow(
      "CompositeDiscountPolicy requires at least one policy",
    );
  });

  describe("sum mode", () => {
    it("sums independent discounts from original subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [
          new PercentageDiscountPolicy(10), // 1000
          new FixedAmountDiscountPolicy(500), // 500
        ],
        "sum",
      );
      expect(composite.computeDiscountCents(10_000)).toBe(1_500);
    });

    it("returns 0 when subtotal is 0", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "sum",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 when subtotal is negative", () => {
      const composite = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(100)],
        "sum",
      );
      expect(composite.computeDiscountCents(-500)).toBe(0);
    });

    it("defaults to sum mode when not specified", () => {
      const composite = new CompositeDiscountPolicy([
        new PercentageDiscountPolicy(10),
        new FixedAmountDiscountPolicy(200),
      ]);
      // sum mode: 10% of 5000 = 500, fixed 200 → 700
      expect(composite.computeDiscountCents(5_000)).toBe(700);
    });
  });

  describe("chain mode", () => {
    it("applies discounts sequentially on remaining subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [
          new PercentageDiscountPolicy(10), // 10% of 10000 = 1000, remaining 9000
          new PercentageDiscountPolicy(10), // 10% of 9000 = 900, remaining 8100
        ],
        "chain",
      );
      expect(composite.computeDiscountCents(10_000)).toBe(1_900);
    });

    it("ordering affects chained results", () => {
      const policyA = new CompositeDiscountPolicy(
        [
          new FixedAmountDiscountPolicy(1_000), // remaining 9000
          new PercentageDiscountPolicy(10),      // 10% of 9000 = 900
        ],
        "chain",
      );
      const policyB = new CompositeDiscountPolicy(
        [
          new PercentageDiscountPolicy(10),      // 10% of 10000 = 1000, remaining 9000
          new FixedAmountDiscountPolicy(1_000),  // min(1000, 9000) = 1000
        ],
        "chain",
      );
      expect(policyA.computeDiscountCents(10_000)).toBe(1_900);
      expect(policyB.computeDiscountCents(10_000)).toBe(2_000);
    });

    it("stops accumulating once remaining hits 0", () => {
      const composite = new CompositeDiscountPolicy(
        [
          new FixedAmountDiscountPolicy(10_000), // takes all 10000
          new PercentageDiscountPolicy(50),       // 50% of 0 = 0
        ],
        "chain",
      );
      expect(composite.computeDiscountCents(10_000)).toBe(10_000);
    });

    it("returns 0 when subtotal is 0", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "chain",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });
  });
});

