import { describe, it, expect, vi } from "vitest";
import {
  NoTaxCalculator,
  RegionalTaxCalculator,
  AsyncTaxCalculator,
  totalLineWeightGrams,
  type AsyncTaxRateProvider,
} from "../src/tax.ts";
import type { CartLine } from "../src/product.ts";

describe("NoTaxCalculator", () => {
  const calc = new NoTaxCalculator();

  it.each([0, 5000, -100])("returns 0 for taxable %i", (taxable) => {
    expect(calc.computeTaxCents(taxable, "US")).toBe(0);
  });
});

describe("RegionalTaxCalculator", () => {
  describe("constructor validation", () => {
    it.each([-0.01, 1.01, NaN, Infinity])(
      "rejects invalid default rate %s",
      (rate) => {
        expect(() => new RegionalTaxCalculator({}, rate)).toThrow(RangeError);
      },
    );

    it("rejects invalid per-region rate", () => {
      expect(
        () => new RegionalTaxCalculator({ "US-CA": 1.5 }),
      ).toThrow(RangeError);
    });

    it("accepts boundary rates 0 and 1", () => {
      expect(
        () => new RegionalTaxCalculator({ "US": 0, "FR": 1 }, 0),
      ).not.toThrow();
    });
  });

  it("looks up region-specific rate", () => {
    const calc = new RegionalTaxCalculator({ "US-CA": 0.0875 });
    // 8.75% of 10000 = 875
    expect(calc.computeTaxCents(10_000, "US-CA")).toBe(875);
  });

  it("falls back to default rate for unknown region", () => {
    const calc = new RegionalTaxCalculator({ "US-CA": 0.0875 }, 0.05);
    // 5% of 10000 = 500
    expect(calc.computeTaxCents(10_000, "DE")).toBe(500);
  });

  it("rounds down fractional cents", () => {
    const calc = new RegionalTaxCalculator({ "US": 0.07 });
    // 7% of 999 = 69.93 → 69
    expect(calc.computeTaxCents(999, "US")).toBe(69);
  });

  it("returns 0 when taxable is 0", () => {
    const calc = new RegionalTaxCalculator({ "US": 0.1 });
    expect(calc.computeTaxCents(0, "US")).toBe(0);
  });

  it("returns 0 when taxable is negative", () => {
    const calc = new RegionalTaxCalculator({ "US": 0.1 });
    expect(calc.computeTaxCents(-500, "US")).toBe(0);
  });

  it("uses default 0 when no default supplied and region unknown", () => {
    const calc = new RegionalTaxCalculator({ "US": 0.1 });
    expect(calc.computeTaxCents(10_000, "XX")).toBe(0);
  });
});

describe("AsyncTaxCalculator", () => {
  it("computes tax from provider rate", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.08),
    };
    const calc = new AsyncTaxCalculator(provider);
    // 8% of 5000 = 400
    expect(await calc.computeTaxCents(5_000, "US")).toBe(400);
    expect(provider.getRate).toHaveBeenCalledWith("US");
  });

  it("rounds down fractional result", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.07),
    };
    const calc = new AsyncTaxCalculator(provider);
    // 7% of 999 = 69.93 → 69
    expect(await calc.computeTaxCents(999, "FR")).toBe(69);
  });

  it("returns 0 when taxable is 0", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.1),
    };
    const calc = new AsyncTaxCalculator(provider);
    expect(await calc.computeTaxCents(0, "US")).toBe(0);
    expect(provider.getRate).not.toHaveBeenCalled();
  });

  it("returns 0 when taxable is negative", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.1),
    };
    const calc = new AsyncTaxCalculator(provider);
    expect(await calc.computeTaxCents(-100, "US")).toBe(0);
  });

  it("throws on invalid rate from provider (> 1)", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(1.5),
    };
    const calc = new AsyncTaxCalculator(provider);
    await expect(calc.computeTaxCents(1_000, "US")).rejects.toThrow(RangeError);
  });

  it("throws on negative rate from provider", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(-0.1),
    };
    const calc = new AsyncTaxCalculator(provider);
    await expect(calc.computeTaxCents(1_000, "US")).rejects.toThrow(RangeError);
  });

  it("throws on NaN rate from provider", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(NaN),
    };
    const calc = new AsyncTaxCalculator(provider);
    await expect(calc.computeTaxCents(1_000, "US")).rejects.toThrow(RangeError);
  });

  it("propagates provider rejection", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockRejectedValue(new Error("network error")),
    };
    const calc = new AsyncTaxCalculator(provider);
    await expect(calc.computeTaxCents(1_000, "US")).rejects.toThrow(
      "network error",
    );
  });
});

describe("totalLineWeightGrams", () => {
  it("sums weight * quantity across lines", () => {
    const lines: CartLine[] = [
      { product: { id: "a", name: "A", unitPriceCents: 100, weightGrams: 200 }, quantity: 2 },
      { product: { id: "b", name: "B", unitPriceCents: 100, weightGrams: 500 }, quantity: 1 },
    ];
    expect(totalLineWeightGrams(lines)).toBe(900);
  });

  it("treats missing weightGrams as 0", () => {
    const lines: CartLine[] = [
      { product: { id: "a", name: "A", unitPriceCents: 100 }, quantity: 3 },
    ];
    expect(totalLineWeightGrams(lines)).toBe(0);
  });

  it("returns 0 for empty lines", () => {
    expect(totalLineWeightGrams([])).toBe(0);
  });
});

